def compute(vars):
    old_rate = vars["v1"]
    new_rate = vars["v2"]

    if old_rate == 0:
        return None

    change_ratio = (new_rate - old_rate) / old_rate
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "old_rate": old_rate,
            "new_rate": new_rate,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
